#!/usr/bin/env node
// Writes the native apps' design tokens and icons (plan D12) from design/tokens.json and design/icons.json:
// apps/ios/BayDesign/Sources/BayTokens.swift and apps/android/core/designsystem/src/main/kotlin/bay/design/BayTokens.kt.
// Colours are written as sRGB, converted from the theme's OKLCH.
//
// Run after changing either file: node packages/mobile-core/scripts/build-design.mjs
// --check fails instead of writing when a generated file is out of date (CI runs it).
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "../../..");
const design = join(root, "packages/mobile-core/design");
const tokens = JSON.parse(readFileSync(join(design, "tokens.json"), "utf8"));
const icons = JSON.parse(readFileSync(join(design, "icons.json"), "utf8"));

const swiftOut = join(root, "apps/ios/BayDesign/Sources/BayTokens.swift");
const kotlinOut = join(root, "apps/android/core/designsystem/src/main/kotlin/bay/design/BayTokens.kt");

const header = "Generated by packages/mobile-core/scripts/build-design.mjs from packages/mobile-core/design. Don't edit.";

// OKLCH (CSS Color 4) to sRGB, each channel 0–255, with alpha 0–1.
function oklch(text) {
  const match = /^oklch\(\s*([\d.]+)(%?)\s+([\d.]+)\s+([\d.]+)\s*(?:\/\s*([\d.]+)(%?))?\s*\)$/.exec(text);

  if (!match) throw new Error(`not an oklch colour: ${text}`);

  const lightness = Number(match[1]) / (match[2] ? 100 : 1);
  const chroma = Number(match[3]);
  const hue = (Number(match[4]) * Math.PI) / 180;
  const alpha = match[5] === undefined ? 1 : Number(match[5]) / (match[6] ? 100 : 1);
  const a = chroma * Math.cos(hue);
  const b = chroma * Math.sin(hue);
  const l = (lightness + 0.3963377774 * a + 0.2158037573 * b) ** 3;
  const m = (lightness - 0.1055613458 * a - 0.0638541728 * b) ** 3;
  const s = (lightness - 0.0894841775 * a - 1.291485548 * b) ** 3;

  const linear = [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];

  const gamma = (value) => (value <= 0.0031308 ? 12.92 * value : 1.055 * value ** (1 / 2.4) - 0.055);
  const [red, green, blue] = linear.map((value) => Math.round(Math.min(1, Math.max(0, gamma(value))) * 255));

  return { red, green, blue, alpha: Math.round(alpha * 1000) / 1000 };
}

function hex(text) {
  const value = Number.parseInt(text.slice(1), 16);

  return { red: (value >> 16) & 255, green: (value >> 8) & 255, blue: value & 255, alpha: 1 };
}

const argb = ({ red, green, blue, alpha }) =>
  "0x" + [Math.round(alpha * 255), red, green, blue].map((channel) => channel.toString(16).padStart(2, "0").toUpperCase()).join("");

const swiftRgba = ({ red, green, blue, alpha }) => `RGBA(${red}, ${green}, ${blue}, ${alpha})`;

const camel = (name) => name.replace(/-(\w)/g, (_, letter) => letter.toUpperCase());

const upper = (name) =>
  camel(name)
    .replace(/([A-Z])/g, "_$1")
    .toUpperCase();

const lines = (entries, render) => Object.entries(entries).map(render).join("\n");

const swiftWeights = { regular: ".regular", medium: ".medium", semibold: ".semibold", bold: ".bold" };
const kotlinWeights = { regular: "FontWeight.Normal", medium: "FontWeight.Medium", semibold: "FontWeight.SemiBold", bold: "FontWeight.Bold" };

const swift = `// ${header}
import SwiftUI

/// Corners. Nested shapes step down the scale: a sheet holds cards, cards hold tiles, tiles hold small controls.
public enum Radius {
${lines(tokens.radius, ([name, value]) => `  public static let ${name}: CGFloat = ${value}`)}
}

/// Spacing on a 4pt grid: \`gutter\` from an edge to content, \`edge\` from the screen to a floating card, \`section\` between blocks.
public enum Space {
${lines(tokens.space, ([name, value]) => `  public static let ${name}: CGFloat = ${value}`)}
}

/// Icon sizes: inside text, small, in rows, in bars and tiles.
public enum IconSize {
${lines(tokens.iconSize, ([name, value]) => `  public static let ${name}: CGFloat = ${value}`)}
}

/// The height of every tappable row.
public enum Row {
  public static let height: CGFloat = ${tokens.rowHeight}
}

/// A step of the type scale: every piece of text in Bay is one of these.
public enum TextVariant: CaseIterable, Sendable {
${Object.keys(tokens.typeScale)
  .map((name) => `  case ${name}`)
  .join("\n")}

  public var size: CGFloat {
    switch self {
${lines(tokens.typeScale, ([name, step]) => `    case .${name}: return ${step.size}`)}
    }
  }

  public var lineHeight: CGFloat {
    switch self {
${lines(tokens.typeScale, ([name, step]) => `    case .${name}: return ${step.lineHeight}`)}
    }
  }

  public var weight: Font.Weight {
    switch self {
${lines(tokens.typeScale, ([name, step]) => `    case .${name}: return ${swiftWeights[step.weight]}`)}
    }
  }

  /// How far the step follows the phone's text size: labels in fixed shapes stop before they spill out.
  public var maxScale: CGFloat {
    switch self {
${lines(tokens.typeScale, ([name, step]) => `    case .${name}: return ${step.maxScale}`)}
    }
  }
}

/// The theme's colours, each with its light and dark value.
public enum BayColor {
${lines(tokens.colors, ([name, value]) => `  public static let ${camel(name)} = Color(light: ${swiftRgba(oklch(value.light))}, dark: ${swiftRgba(oklch(value.dark))})`)}
}

/// The colours settings rows put their icons on, one per kind of setting.
public enum RowTint {
${lines(tokens.rowTint, ([name, value]) => `  public static let ${name == "import" || name == "delete" ? `\`${name}\`` : name} = Color(${swiftRgba(hex(value))})`)}
}

/// Motion: springs for what a finger moves, timings for a tap.
public enum Motion {
  /// Things settling where a finger left them: no overshoot.
  public static let settle = BaySpring(response: ${tokens.motion.settleSpring.response}, dampingRatio: ${tokens.motion.settleSpring.dampingRatio})
  /// A card growing into its page.
  public static let open = BaySpring(response: ${tokens.motion.openSpring.response}, dampingRatio: ${tokens.motion.openSpring.dampingRatio})
  public static let tap: Double = ${tokens.motion.tapMs / 1000}
  public static let settleDuration: Double = ${tokens.motion.settleMs / 1000}
}

/// A start-page wallpaper: a wash from top to bottom under a fine dot grid.
public struct WallpaperPalette: Sendable {
  public let top: Color, middle: Color, bottom: Color, dot: Color
  public let dotOpacity: Double
}

/// Bay's wallpapers, light and dark, by id. Plain (the theme's background) and the user's photo have none.
public enum Wallpapers {
  public static func palette(_ id: String, dark: Bool) -> WallpaperPalette? {
    switch (id, dark) {
${Object.entries(tokens.wallpapers)
  .flatMap(([id, modes]) =>
    Object.entries(modes).map(
      ([mode, p]) =>
        `    case ("${id}", ${mode === "dark"}): return WallpaperPalette(top: Color(${swiftRgba(hex(p.top))}), middle: Color(${swiftRgba(hex(p.middle))}), bottom: Color(${swiftRgba(hex(p.bottom))}), dot: Color(${swiftRgba(hex(p.dot))}), dotOpacity: ${p.dotOpacity})`,
    ),
  )
  .join("\n")}
    default: return nil
    }
  }
}

/// Bay's icons, as SF Symbols.
public enum BayIcon: CaseIterable, Sendable {
${Object.keys(icons)
  .map((name) => `  case ${name == "import" || name == "private" ? `\`${name}\`` : name}`)
  .join("\n")}

  /// The icon a name from the core stands for ("palette", "chevron"), as the Expo app's icon names were.
  public init?(name: String) {
    switch name {
${Object.keys(icons)
  .map((name) => `    case "${name}": self = .${name == "import" || name == "private" ? `\`${name}\`` : name}`)
  .join("\n")}
    default: return nil
    }
  }

  /// The SF Symbol's name.
  public var symbol: String {
    switch self {
${lines(icons, ([name, icon]) => `    case .${name}: return "${icon.sf}"`)}
    }
  }
}
`;

const kotlin = `// ${header}
package bay.design

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

/** Corners. Nested shapes step down the scale: a sheet holds cards, cards hold tiles, tiles hold small controls. */
object Radius {
${lines(tokens.radius, ([name, value]) => `    val ${name} = ${value}.dp`)}
}

/** Spacing on a 4dp grid: \`gutter\` from an edge to content, \`edge\` from the screen to a floating card, \`section\` between blocks. */
object Space {
${lines(tokens.space, ([name, value]) => `    val ${name} = ${value}.dp`)}
}

/** Icon sizes: inside text, small, in rows, in bars and tiles. */
object IconSize {
${lines(tokens.iconSize, ([name, value]) => `    val ${name} = ${value}.dp`)}
}

/** The height of every tappable row. */
object Row {
    val height = ${tokens.rowHeight}.dp
}

/** A step of the type scale: every piece of text in Bay is one of these, in Inter. \`tracking\` matches how San Francisco tracks itself. */
enum class TextVariant(val size: Float, val lineHeight: Float, val weight: FontWeight, val tracking: Float, val maxScale: Float) {
${Object.entries(tokens.typeScale)
  .map(([name, step]) => `    ${upper(name)}(${step.size}f, ${step.lineHeight}f, ${kotlinWeights[step.weight]}, ${step.tracking}f, ${step.maxScale}f)`)
  .join(",\n")};

    val sizeSp get() = size.sp
    val lineHeightSp get() = lineHeight.sp
    val trackingSp get() = tracking.sp
}

/** The theme's colours for one appearance. */
class BayColors(
${Object.keys(tokens.colors)
  .map((name) => `    val ${camel(name)}: Color,`)
  .join("\n")}
)

val LightColors = BayColors(
${lines(tokens.colors, ([name, value]) => `    ${camel(name)} = Color(${argb(oklch(value.light))}),`)}
)

val DarkColors = BayColors(
${lines(tokens.colors, ([name, value]) => `    ${camel(name)} = Color(${argb(oklch(value.dark))}),`)}
)

/** The colours settings rows put their icons on, one per kind of setting. */
object RowTint {
${lines(tokens.rowTint, ([name, value]) => `    val ${name} = Color(${argb(hex(value))})`)}
}

/** Motion: springs for what a finger moves, timings for a tap. */
object Motion {
    /** Things settling where a finger left them: no overshoot. */
    val settle = BaySpring(response = ${tokens.motion.settleSpring.response}f, dampingRatio = ${tokens.motion.settleSpring.dampingRatio}f)

    /** A card growing into its page. */
    val open = BaySpring(response = ${tokens.motion.openSpring.response}f, dampingRatio = ${tokens.motion.openSpring.dampingRatio}f)
    const val TAP_MS = ${tokens.motion.tapMs}
    const val SETTLE_MS = ${tokens.motion.settleMs}
}

/** A start-page wallpaper: a wash from top to bottom under a fine dot grid. */
class WallpaperPalette(val top: Color, val middle: Color, val bottom: Color, val dot: Color, val dotOpacity: Float)

/** Bay's wallpapers, light and dark, by id. Plain (the theme's background) and the user's photo have none. */
fun wallpaperPalette(id: String, dark: Boolean): WallpaperPalette? = when {
${Object.entries(tokens.wallpapers)
  .flatMap(([id, modes]) =>
    Object.entries(modes).map(
      ([mode, p]) =>
        `    id == "${id}" && ${mode === "dark" ? "dark" : "!dark"} -> WallpaperPalette(Color(${argb(hex(p.top))}), Color(${argb(hex(p.middle))}), Color(${argb(hex(p.bottom))}), Color(${argb(hex(p.dot))}), ${p.dotOpacity}f)`,
    ),
  )
  .join("\n")}
    else -> null
}

/** Bay's icons: Material Symbols Outlined on a 960-unit grid (google/material-design-icons, Apache-2.0). */
enum class BayIcon(val path: String, val lifted: Boolean = false) {
${Object.entries(icons)
  .map(([name, icon]) => `    ${upper(name)}("${icon.material}"${icon.lifted ? ", lifted = true" : ""})`)
  .join(",\n")};

    companion object {
        /** The icon a name from the core stands for ("palette", "chevron"), as the Expo app's icon names were. */
        fun named(name: String): BayIcon? = when (name) {
${Object.keys(icons)
  .map((name) => `            "${name}" -> ${upper(name)}`)
  .join("\n")}
            else -> null
        }
    }
}
`;

const outputs = [
  [swiftOut, swift],
  [kotlinOut, kotlin],
];

if (process.argv.includes("--check")) {
  const stale = outputs.filter(([path, text]) => {
    try {
      return readFileSync(path, "utf8") !== text;
    } catch {
      // Missing: out of date.
      return true;
    }
  });

  if (stale.length > 0) {
    console.error(`out of date: ${stale.map(([path]) => path.slice(root.length + 1)).join(", ")}; run node packages/mobile-core/scripts/build-design.mjs`);
    process.exit(1);
  }
} else {
  for (const [path, text] of outputs) writeFileSync(path, text);
  console.log("wrote BayTokens.swift and BayTokens.kt");
}
